(()=>{
'use strict';
if(window.GTAVBenchmarkLab)return;
let lab=null,selected='balanced';
const presets={
 saver:{name:'Battery Saver',note:'Lowest load',desc:'Prioritizes stability, temperature and memory headroom.'},
 balanced:{name:'Balanced',note:'Recommended start',desc:'A practical starting point for most supported devices.'},
 performance:{name:'Performance',note:'60 FPS target',desc:'Reduces image cost to chase higher frame rate on stronger devices.'},
 quality:{name:'Quality',note:'Image quality',desc:'Higher visual quality with a lower frame-rate target.'},
 custom:{name:'Custom',note:'Your settings',desc:'Test the exact graphics configuration you already use.'}
};
function cardText(label){const cards=[...document.querySelectorAll('#hardware-grid .hardware-card')];const c=cards.find(x=>x.querySelector('.hardware-label')?.textContent.trim().toLowerCase()===label.toLowerCase());return c?.querySelector('h3')?.textContent.trim()||''}
function hardware(){const chip=cardText('System on chip'),ram=parseFloat(cardText('Installed RAM'))||0,m=/A(\d+)/i.exec(chip);return{chip,ram,a:m?+m[1]:0}}
function suggest(){const h=hardware();if(h.a===12||h.ram<4)return'saver';if(h.ram<=4.5||h.a===13||h.a===14)return'balanced';if(h.ram>=8&&h.a>=17)return'quality';if(h.ram>=6&&h.a>=15)return'performance';return'balanced'}
function settings(id){const h=hardware(),low=h.ram>0&&h.ram<=4.5,texture=h.ram>=8?'Very High':h.ram>=6?'High':'Normal';let res='960×540',cap='30 FPS',aa='Off',fx='Auto';if(id==='saver'){res='854×480 / 960×540'}if(id==='balanced'){res=h.a>=15&&h.ram>=6?'1280×720':'960×540';cap=h.a>=15?'40 FPS':'30 FPS'}if(id==='performance'){res=h.a>=17?'1280×720':'960×540';cap='60 FPS'}if(id==='quality'){res=h.a>=17&&h.ram>=8?'1600×900':'1280×720';cap='30–40 FPS';aa='TAA'}if(id==='custom'){res=cap=aa=fx='Current value'}return{Resolution:res,Textures:id==='custom'?'Current value':texture,'Low-memory':id==='custom'?'Current value':low?'On':'Auto',AA:aa,MetalFX:fx,'Frame cap':cap}}
function parseSummary(text){const passes=[];let section='';for(const raw of text.split(/\r?\n/)){const line=raw.trim();if(/Frames Per Second/i.test(line)){section='fps';continue}if(/Frames under 33ms/i.test(line)){section='30';continue}let m;if(section==='fps'&&(m=/^Pass\s+(\d+)\s*,\s*([\d.]+)\s*,\s*([\d.]+)\s*,\s*([\d.]+)/i.exec(line))){passes.push({pass:+m[1],min:+m[2],max:+m[3],avg:+m[4]});continue}if(section==='30'&&(m=/^Pass\s+(\d+):\s*(\d+)\/(\d+)\s+frames\s*\(([\d.]+)%\)/i.exec(line))){let p=passes.find(x=>x.pass===+m[1]);if(!p){p={pass:+m[1]};passes.push(p)}p.under33=+m[4]}}return passes.filter(p=>Number.isFinite(p.avg))}
function parseFrameTimes(text){const vals=text.split(/\s+/).map(Number).filter(n=>Number.isFinite(n)&&n>0&&n<1000);if(vals.length<30)return[];const median=[...vals].sort((a,b)=>a-b)[Math.floor(vals.length/2)];const ms=median>1;return vals.map(v=>ms?1000/v:v).filter(v=>v>1&&v<500)}
function avg(a){return a.length?a.reduce((x,y)=>x+y,0)/a.length:0}
function ensure(){if(lab)return;const style=document.createElement('style');style.textContent=`
body.benchmark-open #compat-results>*:not(#fps-benchmark-lab){display:none!important}.fps-lab{max-width:900px;margin:0 auto}.fps-head{display:flex;justify-content:space-between;gap:20px;align-items:start;padding-bottom:18px;border-bottom:1px solid rgba(255,255,255,.1)}.fps-head h2{margin:6px 0 5px;font-size:34px;letter-spacing:-1px}.fps-head p{margin:0;max-width:620px;color:#7d7d7d;font-size:10px;line-height:1.6}.fps-back{border:0;background:none;color:#aaa;font:500 10px 'DM Sans',sans-serif;padding:8px 0}.fps-flow{display:flex;gap:18px;padding:13px 0;border-bottom:1px solid rgba(255,255,255,.08);color:#656565;font-size:8px}.fps-presets{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px;padding:18px 0}.fps-preset{padding:13px;text-align:left;border:1px solid rgba(255,255,255,.1);border-radius:7px;background:rgba(255,255,255,.02);color:#ddd}.fps-preset[aria-pressed=true]{border-color:rgba(120,183,215,.45);background:rgba(120,183,215,.05)}.fps-preset b{display:block;font-size:10px}.fps-preset small{display:block;margin-top:5px;color:#6b6b6b;font-size:7px;line-height:1.4}.fps-detail{display:grid;grid-template-columns:1fr 1fr;gap:20px;padding:17px 0;border-top:1px solid rgba(255,255,255,.08);border-bottom:1px solid rgba(255,255,255,.08)}.fps-detail h3{margin:5px 0;font-size:16px}.fps-detail p{margin:0;color:#737373;font-size:8px;line-height:1.6}.fps-settings{display:grid;grid-template-columns:1fr 1fr;gap:8px 14px}.fps-settings span{color:#656565;font-size:7px}.fps-settings b{display:block;margin-top:3px;color:#ccc;font-size:9px;font-weight:500}.fps-import{display:grid;grid-template-columns:1fr auto;gap:18px;align-items:center;padding:20px 0}.fps-import strong{font-size:11px}.fps-import p{margin:5px 0 0;color:#696969;font-size:8px}.fps-import input{max-width:280px;color:#777;font-size:8px}.fps-error{grid-column:1/-1;color:#e8837b;font-size:8px}.fps-output{padding-top:18px;border-top:1px solid rgba(255,255,255,.08)}.fps-output[hidden]{display:none!important}.fps-output h3{margin:5px 0 4px;font-size:20px}.fps-output p{margin:0;color:#777;font-size:8px}.fps-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:13px}.fps-metrics div{padding:13px;border:1px solid rgba(255,255,255,.1);border-radius:7px;background:rgba(255,255,255,.02)}.fps-metrics span{display:block;color:#666;font-size:7px;text-transform:uppercase}.fps-metrics strong{display:block;margin-top:6px;font-size:20px}.fps-rec{margin-top:12px!important;line-height:1.6!important}@media(max-width:700px){.fps-presets{grid-template-columns:1fr 1fr}.fps-preset:last-child{grid-column:1/-1}.fps-detail,.fps-import{grid-template-columns:1fr}.fps-metrics{grid-template-columns:1fr 1fr}.fps-head{display:block}.fps-back{margin-top:12px}}
`;document.head.append(style);
 lab=document.createElement('section');lab.id='fps-benchmark-lab';lab.className='fps-lab';lab.innerHTML=`<div class="fps-head"><div><span class="fps-kicker">NATIVE GAME TEST</span><h2>FPS Benchmark</h2><p>Choose a preset, run GTA V’s built-in Benchmark in the launcher, then import its result. Safari only analyzes the file.</p></div><button type="button" class="fps-back">Back to compatibility</button></div><div class="fps-flow"><span>1 Choose preset</span><span>2 Run Benchmark</span><span>3 Import result</span></div><div class="fps-presets"></div><div class="fps-detail"><div><span>SELECTED PRESET</span><h3 id="fps-title"></h3><p id="fps-copy"></p></div><div class="fps-settings" id="fps-settings"></div></div><div class="fps-import"><div><strong>Import benchmark result</strong><p>Benchmark-*.txt; optionally add FrameTimes-Pass*.txt for 1% low.</p></div><input id="fps-files" type="file" accept=".txt,.log,text/plain" multiple><div class="fps-error" id="fps-error" hidden></div></div><div class="fps-output" id="fps-output" hidden><span>RESULT</span><h3 id="fps-rating"></h3><p id="fps-context"></p><div class="fps-metrics"><div><span>Average</span><strong id="fps-avg">—</strong></div><div><span>1% low</span><strong id="fps-low">—</strong></div><div><span>Minimum</span><strong id="fps-min">—</strong></div><div><span>30 FPS pacing</span><strong id="fps-pacing">—</strong></div></div><p class="fps-rec" id="fps-rec"></p></div>`;
 document.querySelector('#compat-results')?.prepend(lab);
 const box=lab.querySelector('.fps-presets');for(const [id,p] of Object.entries(presets)){const b=document.createElement('button');b.type='button';b.className='fps-preset';b.dataset.preset=id;b.innerHTML=`<b>${p.name}</b><small>${p.note}</small>`;box.append(b)}
 box.addEventListener('click',e=>{const b=e.target.closest('.fps-preset');if(b)select(b.dataset.preset)});lab.querySelector('.fps-back').addEventListener('click',close);lab.querySelector('#fps-files').addEventListener('change',readFiles);select(suggest());
}
function select(id){selected=id;if(!lab)return;lab.querySelectorAll('.fps-preset').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.preset===id)));lab.querySelector('#fps-title').textContent=presets[id].name;lab.querySelector('#fps-copy').textContent=presets[id].desc;const g=lab.querySelector('#fps-settings');g.replaceChildren();for(const [k,v] of Object.entries(settings(id))){const s=document.createElement('span');s.textContent=k;const b=document.createElement('b');b.textContent=v;s.append(b);g.append(s)}}
async function readFiles(e){const files=[...e.target.files],err=lab.querySelector('#fps-error'),out=lab.querySelector('#fps-output');err.hidden=true;out.hidden=true;if(!files.length)return;try{let passes=[],frames=[];for(const f of files){const t=await f.text();if(/FrameTimes/i.test(f.name))frames.push(...parseFrameTimes(t));else passes.push(...parseSummary(t))}if(!passes.length)throw new Error('No GTA V benchmark FPS summary was found in the selected file.');const average=avg(passes.map(p=>p.avg)),minimum=Math.min(...passes.map(p=>p.min)),pacingVals=passes.map(p=>p.under33).filter(Number.isFinite),pacing=pacingVals.length?avg(pacingVals):null;let low=null;if(frames.length){const sorted=[...frames].sort((a,b)=>a-b),n=Math.max(1,Math.floor(sorted.length*.01));low=avg(sorted.slice(0,n))}const rating=average>=55&&(low==null||low>=40)?'Strong 60 FPS result':average>=38?'Good playable result':average>=28?'30 FPS class':'Below recommended';lab.querySelector('#fps-rating').textContent=rating;lab.querySelector('#fps-context').textContent=`${presets[selected].name} · ${passes.length} benchmark pass${passes.length===1?'':'es'}`;lab.querySelector('#fps-avg').textContent=average.toFixed(1);lab.querySelector('#fps-min').textContent=minimum.toFixed(1);lab.querySelector('#fps-low').textContent=low==null?'—':low.toFixed(1);lab.querySelector('#fps-pacing').textContent=pacing==null?'—':pacing.toFixed(1)+'%';let rec=average<28?'Try Battery Saver and reduce resolution.':average<45?'Balanced is the safer target for smoother frame pacing.':average>=55?'You can test a higher-quality preset next.':'Keep this preset and compare 1% low before increasing quality.';lab.querySelector('#fps-rec').textContent=rec;out.hidden=false;out.scrollIntoView({behavior:'smooth',block:'nearest'})}catch(x){err.textContent=x.message||'Could not read this benchmark file.';err.hidden=false}}
function open(){ensure();document.body.classList.add('benchmark-open');select(suggest());window.scrollTo({top:0,behavior:'smooth'})}
function close(){document.body.classList.remove('benchmark-open');document.querySelector('#compat-result-title')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'smooth'})}
window.GTAVBenchmarkLab={open,close};
})();